"  useEffect(() => {
    localStorage.setItem('pos_terminal_settings', JSON.stringify(posSettings));
  }, [posSettings]);

  useEffect(() => {
    if (window.require) {
      try {
        const { ipcRenderer } = window.require('electron');
        ipcRenderer.invoke('get-printers')
          .then(printers => {
            if (Array.isArray(printers) && printers.length > 0) {
              const mapped = printers.map((p, idx) => ({
                name: p.name,
                id: `printer_${idx}_${p.name.replace(/\s+/g, '_')}`
              }));
              setAvailablePrinters(mapped);
            }
          })
          .catch(err => {
            console.error('[React] Error fetching printer list:', err);
          });
      } catch (err) {
        console.warn('[React] Electron ipcRenderer not available:', err);
      }
    }
  }, []);"
